import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"Harness 工程宣言","description":"","frontmatter":{"title":"Harness 工程宣言","date":"2026-06-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/Harness工程宣言.md","filePath":"posts/Harness工程宣言.md"}'),d={name:"posts/Harness工程宣言.md"};function p(r,a,l,i,o,h){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="harness-工程宣言" tabindex="-1">Harness 工程宣言 <a class="header-anchor" href="#harness-工程宣言" aria-label="Permalink to &quot;Harness 工程宣言&quot;">​</a></h1><blockquote><p>什么是 Harness，为什么这个项目是 Harness 2026-06-12 · 最终确认</p></blockquote><hr><h2 id="一、这是-harness-吗" tabindex="-1">一、这是 Harness 吗？ <a class="header-anchor" href="#一、这是-harness-吗" aria-label="Permalink to &quot;一、这是 Harness 吗？&quot;">​</a></h2><p><strong>是的，这个项目是 Harness。</strong></p><h3 id="harness-的定义" tabindex="-1">Harness 的定义 <a class="header-anchor" href="#harness-的定义" aria-label="Permalink to &quot;Harness 的定义&quot;">​</a></h3><p>Harness（马具）在软件工程中是一种<strong>骨架型基础设施</strong>——它不产生业务价值，而是协调多个独立组件协同工作。</p><h3 id="判断标准" tabindex="-1">判断标准 <a class="header-anchor" href="#判断标准" aria-label="Permalink to &quot;判断标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>本项目</th><th>说明</th></tr></thead><tbody><tr><td>不写业务代码</td><td>✅</td><td>不实现 JWT、不写 CRUD、不做 UI</td></tr><tr><td>只搭协作框架</td><td>✅</td><td>STATUS.md 协议 + n8n 路由 + SKILL.md</td></tr><tr><td>协调多个进程</td><td>✅</td><td>Hermes → CC → Codex 三 Agent</td></tr><tr><td>各层可独立替换</td><td>✅</td><td>路由层/会话层/协议层解耦</td></tr><tr><td>体积小、模块化</td><td>✅</td><td>整套在 project-archive 项目内，不侵入业务项目</td></tr><tr><td>定义通信协议</td><td>✅</td><td>STATUS.md 读写规范 + commit 消息约定</td></tr></tbody></table><hr><h2 id="二、跟传统框架的本质区别" tabindex="-1">二、跟传统框架的本质区别 <a class="header-anchor" href="#二、跟传统框架的本质区别" aria-label="Permalink to &quot;二、跟传统框架的本质区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>框架（Framework）</th><th>Harness（马具）</th></tr></thead><tbody><tr><td>立场</td><td>&quot;你的代码按我的方式写&quot;</td><td>&quot;你的代码继续你的方式，我只管通信&quot;</td></tr><tr><td>侵入性</td><td>需要 import / 继承</td><td>零侵入（文件协议）</td></tr><tr><td>升级</td><td>框架大版本可能有 breaking change</td><td>不改协议就不受影响</td></tr><tr><td>心智负担</td><td>高（学 API / 注解 / 生命周期）</td><td>低（一个文件 + 几条规则）</td></tr><tr><td>调试</td><td>黑箱，框架内部不可见</td><td>全透明，STATUS.md 就是日志</td></tr><tr><td>可替换性</td><td>切框架等于重写</td><td>换路由层不改协议</td></tr></tbody></table><hr><h2 id="三、agent-的商品化" tabindex="-1">三、Agent 的商品化 <a class="header-anchor" href="#三、agent-的商品化" aria-label="Permalink to &quot;三、Agent 的商品化&quot;">​</a></h2><p>这个 Harness 的设计前提：</p><blockquote><p><strong>Agent 是商品，Harness 是差异化的。</strong></p></blockquote><ul><li>Claude Code 会变，Codex 会变，模型会变</li><li>但 <strong>CC 写代码 → Codex 审查 → 循环直到通过</strong> 这个模式不会变</li><li>Harness 就是把这个模式固定下来，让底层 Agent 可替换</li></ul><p>现在用的是 CC + Codex，明天换了 OpenCode + Claude Code 3？<strong>Harness 不变，改 SKILL.md 里的触发命令就行。</strong></p><hr><h2 id="四、三层架构的可替换性" tabindex="-1">四、三层架构的可替换性 <a class="header-anchor" href="#四、三层架构的可替换性" aria-label="Permalink to &quot;四、三层架构的可替换性&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>┌──────────────┐</span></span>
<span class="line"><span>│   路由层     │  n8n → Dify → LangGraph → 自建脚本</span></span>
<span class="line"><span>├──────────────┤  都行，只要做好一件事：收到事件 → 决策 → 注入</span></span>
<span class="line"><span>│   会话层     │  Windows终端 → WSL tmux → Docker exec</span></span>
<span class="line"><span>├──────────────┤  都行，只要 Agent 能收到命令</span></span>
<span class="line"><span>│   协议层     │  STATUS.md → JSON → 数据库</span></span>
<span class="line"><span>└──────────────┘  都行，只要 Agent 能读能写</span></span></code></pre></div><p>每一层都是一个协议接口。不改协议就能换实现。</p><hr><h2 id="五、跟-langgraph-的对比" tabindex="-1">五、跟 LangGraph 的对比 <a class="header-anchor" href="#五、跟-langgraph-的对比" aria-label="Permalink to &quot;五、跟 LangGraph 的对比&quot;">​</a></h2><p>LangGraph 是多 Agent 图编排框架，跟本 Harness 是两回事：</p><table tabindex="0"><thead><tr><th>维度</th><th>LangGraph</th><th>本 Harness</th></tr></thead><tbody><tr><td>通信</td><td>Python 函数调用</td><td>文件系统（STATUS.md）</td></tr><tr><td>Agent 运行</td><td>子进程/线程</td><td>持久终端窗口</td></tr><tr><td>状态</td><td>内存 graph_state</td><td>磁盘文件</td></tr><tr><td>可调试</td><td>断点 + print</td><td>直接看文件 + git log</td></tr><tr><td>耦合</td><td>代码级耦合</td><td>协议级耦合</td></tr><tr><td>上手成本</td><td>学 LangGraph API</td><td>知道 STATUS.md 怎么写就行</td></tr></tbody></table><p><strong>LangGraph 适合：</strong> 纯代码内编排、函数级的 Agent 调用 <strong>本 Harness 适合：</strong> 独立 CLI Agent 窗口、文件系统协议、事件驱动</p><hr><h2 id="六、为什么不做成框架" tabindex="-1">六、为什么不做成框架 <a class="header-anchor" href="#六、为什么不做成框架" aria-label="Permalink to &quot;六、为什么不做成框架&quot;">​</a></h2><p>用户说过一句话：</p><blockquote><p>&quot;不灵活你知道吗，我如果修改节点又做不到了，只能靠跟你吵架。我不能手动修改。&quot;</p></blockquote><p><strong>Harness 的设计目标就是不让用户吵架。</strong> 所有文件都是：</p><ul><li>打开的（TXT/MD，不是二进制）</li><li>可读的（中文说明 + 表格）</li><li>可改的（记事本就能改）</li></ul><p>不依赖我，不依赖任何 Agent，一个人一把记事本就能看懂全部。</p><hr><h2 id="七、最终架构图" tabindex="-1">七、最终架构图 <a class="header-anchor" href="#七、最终架构图" aria-label="Permalink to &quot;七、最终架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>                用户需求</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>               ┌────┴────┐</span></span>
<span class="line"><span>               │ Hermes  │  规划 + 终审</span></span>
<span class="line"><span>               └────┬────┘</span></span>
<span class="line"><span>                    │ STATUS.md</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│               n8n 路由层                  │</span></span>
<span class="line"><span>│  git commit → webhook → 决策 → inject    │</span></span>
<span class="line"><span>└────┬──────────────────────────────┬──────┘</span></span>
<span class="line"><span>     │ tmux send-keys               │ tmux send-keys</span></span>
<span class="line"><span>     ▼                              ▼</span></span>
<span class="line"><span>┌────────────┐              ┌────────────┐</span></span>
<span class="line"><span>│   CC       │              │  Codex     │</span></span>
<span class="line"><span>│ 发散·实现  │◄────STATUS.md──► 收敛·审查  │</span></span>
<span class="line"><span>└─────┬──────┘  文件协议     └─────┬──────┘</span></span>
<span class="line"><span>      │ git commit                │ git commit</span></span>
<span class="line"><span>      │ curl POST n8n             │ curl POST n8n</span></span>
<span class="line"><span>      └──────────────┬────────────┘</span></span>
<span class="line"><span>                     │ 循环</span></span>
<span class="line"><span>                     ▼</span></span>
<span class="line"><span>              REVIEW-PASS</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>               ┌────┴────┐</span></span>
<span class="line"><span>               │ Hermes  │  归档</span></span>
<span class="line"><span>               └─────────┘</span></span></code></pre></div><p><strong>这是 Harness，不是框架。</strong></p>`,38)])])}const b=s(d,[["render",p]]);export{g as __pageData,b as default};
